import { spawn } from 'node:child_process';

// Everything that touches FFmpeg: argument builders (pure, so they are tested without the
// program) and a runner that never goes through a shell. File names in the arguments are
// always generated by the server; user text only ever reaches FFmpeg inside a subtitle file.
export const WIDTH = 1080;
export const HEIGHT = 1920;
export const FPS = 30;

export type Fit = 'cover' | 'contain';
export type FitOptions = {
  fit: Fit;
  rotate: 0 | 90 | 180 | 270;
  brightness: number;
  contrast: number;
  saturation: number;
};

const rotation: Record<number, string> = {
  0: '',
  90: 'transpose=1,',
  180: 'hflip,vflip,',
  270: 'transpose=2,',
};

// A still photo made 9:16: "cover" crops to fill, "contain" keeps the whole photo on a
// blurred copy of itself. Colour adjustments come last.
export function fitArgs(
  input: string,
  output: string,
  o: FitOptions,
): string[] {
  const rotate = rotation[o.rotate]!;
  const eq = `eq=brightness=${o.brightness}:contrast=${o.contrast}:saturation=${o.saturation}`;
  const graph =
    o.fit === 'cover'
      ? `[0:v]${rotate}scale=${WIDTH}:${HEIGHT}:force_original_aspect_ratio=increase,crop=${WIDTH}:${HEIGHT},${eq}[out]`
      : `[0:v]${rotate}split[a][b];[a]scale=${WIDTH}:${HEIGHT}:force_original_aspect_ratio=increase,crop=${WIDTH}:${HEIGHT},boxblur=30:5[bg];` +
        `[b]scale=${WIDTH}:${HEIGHT}:force_original_aspect_ratio=decrease[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,${eq}[out]`;
  return [
    '-y',
    '-hide_banner',
    '-i',
    input,
    '-filter_complex',
    graph,
    '-map',
    '[out]',
    '-frames:v',
    '1',
    '-q:v',
    '2',
    output,
  ];
}

export type Scene = {
  // A photo, or a video clip when `video` is true (then it is cut from `trimStart`).
  image: string;
  seconds: number;
  text: string;
  video?: boolean;
  trimStart?: number;
  // A backdrop photo; the scene image is then shown inside it instead of filling the frame.
  background?: string | null;
};
export type RenderPlan = {
  scenes: Scene[];
  transition: 'none' | 'fade';
  motion: 'none' | 'zoom';
  music: string | null;
  output: string;
  // Name of the subtitle file, relative to the working directory FFmpeg runs in.
  subtitles: string;
};

export const totalSeconds = (scenes: Scene[]) =>
  scenes.reduce((sum, s) => sum + s.seconds, 0);

const stamp = (seconds: number) => {
  const ms = Math.round(seconds * 1000);
  const p = (n: number, w = 2) => String(n).padStart(w, '0');
  return `${p(Math.floor(ms / 3_600_000))}:${p(Math.floor(ms / 60_000) % 60)}:${p(Math.floor(ms / 1000) % 60)},${p(ms % 1000, 3)}`;
};

// One subtitle per scene that has text, timed from the scene lengths.
export function subtitleFile(scenes: Scene[]): string {
  let at = 0;
  const blocks: string[] = [];
  for (const scene of scenes) {
    const text = scene.text
      .replace(/<[^>]*>/g, '')
      .replace(/\r/g, '')
      .trim();
    if (text)
      blocks.push(
        `${blocks.length + 1}\n${stamp(at)} --> ${stamp(at + scene.seconds - 0.05)}\n${text}\n`,
      );
    at += scene.seconds;
  }
  return blocks.join('\n');
}

export function renderArgs(plan: RenderPlan): string[] {
  const { scenes } = plan;
  const total = totalSeconds(scenes);
  const args = ['-y', '-hide_banner', '-nostats', '-progress', 'pipe:1'];
  let next = 0;
  // Adds one input and returns its index; stills loop for the scene length, clips are cut.
  const input = (path: string, scene: Scene, clip: boolean) => {
    if (clip)
      args.push(
        '-ss',
        String(scene.trimStart ?? 0),
        '-t',
        String(scene.seconds),
        '-i',
        path,
      );
    else
      args.push(
        '-loop',
        '1',
        '-framerate',
        String(FPS),
        '-t',
        String(scene.seconds),
        '-i',
        path,
      );
    return next++;
  };

  const parts: string[] = [];
  scenes.forEach((scene, i) => {
    const bg = scene.background ? input(scene.background, scene, false) : null;
    const fg = input(scene.image, scene, Boolean(scene.video));
    // A clip is held on its last frame if it is shorter than the scene, then cut to length.
    const prep = scene.video
      ? `fps=${FPS},tpad=stop_mode=clone:stop_duration=${scene.seconds},trim=duration=${scene.seconds},setpts=PTS-STARTPTS,`
      : '';
    if (bg !== null) {
      parts.push(
        `[${bg}:v]scale=${WIDTH}:${HEIGHT}:force_original_aspect_ratio=increase,crop=${WIDTH}:${HEIGHT},setsar=1[b${i}]`,
      );
      parts.push(
        `[${fg}:v]${prep}scale=${WIDTH - 160}:${HEIGHT - 620}:force_original_aspect_ratio=decrease,setsar=1[f${i}]`,
      );
      parts.push(`[b${i}][f${i}]overlay=(W-w)/2:(H-h)/2[c${i}]`);
    } else {
      parts.push(
        `[${fg}:v]${prep}scale=${WIDTH}:${HEIGHT}:force_original_aspect_ratio=increase,crop=${WIDTH}:${HEIGHT},setsar=1[c${i}]`,
      );
    }
    // The zoom works on a larger copy so it moves smoothly instead of jumping pixel by pixel.
    const motion =
      plan.motion === 'zoom' && !scene.video
        ? `scale=${(WIDTH * 3) / 2}:${(HEIGHT * 3) / 2},zoompan=z='min(zoom+0.0008,1.12)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=${WIDTH}x${HEIGHT}:fps=${FPS},`
        : '';
    const fade =
      plan.transition === 'fade'
        ? `,fade=t=in:st=0:d=0.3,fade=t=out:st=${Math.max(0, scene.seconds - 0.3)}:d=0.3`
        : '';
    parts.push(`[c${i}]${motion}format=yuv420p${fade}[v${i}]`);
  });
  parts.push(
    `${scenes.map((_, i) => `[v${i}]`).join('')}concat=n=${scenes.length}:v=1:a=0[joined]`,
  );
  const style =
    "force_style='FontName=Arial,FontSize=11,Bold=1,Outline=2,Shadow=0,Alignment=2,MarginV=45'";
  const hasText = scenes.some((s) => s.text.trim());
  parts.push(
    hasText
      ? `[joined]subtitles=${plan.subtitles}:${style}[vout]`
      : '[joined]null[vout]',
  );

  // The music input comes after every scene input.
  if (plan.music) {
    args.push('-i', plan.music);
    // Music is padded or cut to the video length and fades out in the last second.
    parts.push(
      `[${next}:a]apad,atrim=0:${total},afade=t=out:st=${Math.max(0, total - 1)}:d=1[aout]`,
    );
  }

  args.push('-filter_complex', parts.join(';'), '-map', '[vout]');
  if (plan.music) args.push('-map', '[aout]');
  args.push(
    '-t',
    String(total),
    '-c:v',
    'libx264',
    '-preset',
    'veryfast',
    '-crf',
    '23',
    '-pix_fmt',
    'yuv420p',
    '-r',
    String(FPS),
    ...(plan.music ? ['-c:a', 'aac', '-b:a', '160k'] : ['-an']),
    '-movflags',
    '+faststart',
    plan.output,
  );
  return args;
}

export type RunResult = {
  code: number | null;
  stdout: string;
  stderr: string;
  timedOut: boolean;
};

// Runs FFmpeg without a shell. `onProgress` gets the seconds rendered so far.
export function run(
  program: string,
  args: string[],
  options: {
    cwd?: string;
    timeoutMs: number;
    onProgress?: (seconds: number) => void;
  },
): Promise<RunResult> {
  return new Promise((resolve) => {
    const child = spawn(program, args, {
      cwd: options.cwd,
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill();
    }, options.timeoutMs);
    child.stdout.on('data', (chunk: Buffer) => {
      // Only the start is kept (enough for `-version`); progress lines are read below.
      if (stdout.length < 500) stdout += chunk.toString();
      for (const line of chunk.toString().split('\n')) {
        const match = /^out_time_(?:us|ms)=(\d+)/.exec(line.trim());
        if (match) options.onProgress?.(Number(match[1]) / 1_000_000);
      }
    });
    child.stderr.on('data', (chunk: Buffer) => {
      stderr = (stderr + chunk.toString()).slice(-4000);
    });
    child.on('error', (error) => {
      clearTimeout(timer);
      resolve({ code: null, stdout, stderr: error.message, timedOut: false });
    });
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, stdout, stderr, timedOut });
    });
  });
}

// Width, height and length of an image or video, read with ffprobe.
export async function probe(ffprobe: string, file: string) {
  const out: string[] = [];
  const result = await new Promise<number | null>((resolve) => {
    const child = spawn(
      ffprobe,
      [
        '-v',
        'error',
        '-select_streams',
        'v:0',
        '-show_entries',
        'stream=width,height:format=duration',
        '-of',
        'json',
        file,
      ],
      {
        windowsHide: true,
        stdio: ['ignore', 'pipe', 'ignore'],
      },
    );
    child.stdout.on('data', (c: Buffer) => out.push(c.toString()));
    child.on('error', () => resolve(null));
    child.on('close', resolve);
  });
  if (result !== 0) return null;
  try {
    const data = JSON.parse(out.join('')) as {
      streams?: { width?: number; height?: number }[];
      format?: { duration?: string };
    };
    const s = data.streams?.[0];
    return {
      width: s?.width ?? null,
      height: s?.height ?? null,
      seconds: data.format?.duration ? Number(data.format.duration) : null,
    };
  } catch {
    return null;
  }
}
